create or replace function public.is_team_member(t uuid) returns boolean
language sql security definer stable set search_path = '' as $$
  select exists (select 1 from public.team_members
                 where team_id = t and user_id = auth.uid());
$$;

drop policy if exists "members can read" on public.team_members;
create policy "members can read" on public.team_members for select
  to authenticated using ( public.is_team_member(team_id) );
